/**
 * OptionIsDefined eval — fixture-driven test (phase 2f medium Stop β Task 4).
 *
 * Tests the `OptionIsDefined` arm of the evaluator. OptionIsDefined returns
 * Boolean(true) for Some, Boolean(false) for None; throws
 * 'option-input-not-option' on non-Option input.
 *
 * Cost: Fixed(10), charged BEFORE eval-child (Pattern A).
 * Sigma-rust ref: ergotree-interpreter/src/eval/option_is_defined.rs:9-24
 *
 * Fixtures generated by `fixture-gen/src/cmds/ergoscript/eval/option_is_defined.rs`
 * (sigma-rust oracle; byte-equality check).
 */

import { describe, it, expect } from 'vitest'
import { readFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { parseTree } from '../../src/wire/ergo-tree'
import { evaluate, evaluateWith } from '../../src/eval/evaluate'
import { makeContext } from '../../src/eval/eval-context'
import { hexToBytes, hydrateSValue, captureEvalError, rehydrateEvalOpts } from '../_helpers'

const __dirname = dirname(fileURLToPath(import.meta.url))

interface OptionIsDefinedFixtureEntry {
  name: string
  tree_bytes_hex: string
  opts_json: Record<string, unknown>
  expected_value_json: unknown
  expected_cost: number
  expected_error_code: string | null
}

interface OptionIsDefinedFixtureFile {
  corpus: string
  entries: OptionIsDefinedFixtureEntry[]
}

const FIXTURE_PATH = join(__dirname, '../fixtures/eval/option-is-defined.json')
const fixture: OptionIsDefinedFixtureFile = JSON.parse(readFileSync(FIXTURE_PATH, 'utf-8'))

describe('OptionIsDefined eval (phase 2f medium Stop β Task 4)', () => {
  for (const entry of fixture.entries) {
    it(entry.name, () => {
      const tree = parseTree(hexToBytes(entry.tree_bytes_hex))
      const opts = rehydrateEvalOpts(entry.opts_json)
      const ctx = makeContext(opts)

      if (entry.expected_error_code !== null) {
        const err = captureEvalError(() => evaluateWith(tree, ctx))
        expect(err.code).toBe(entry.expected_error_code)
      } else {
        const result = evaluateWith(tree, ctx)
        expect(result).toEqual(hydrateSValue(entry.expected_value_json))
        expect(ctx.jitCost).toBe(entry.expected_cost)
      }
    })
  }

  it("non-Option input throws 'option-input-not-option'", () => {
    const tree = {
      header: { version: 0 as const, hasSize: false, constantSegregation: false, rawHeader: 0 },
      constants: [] as [],
      constantTypes: [] as [],
      body: {
        tag: 'OptionIsDefined' as const,
        input: {
          tag: 'Const' as const,
          tpe: { tag: 'SInt' as const },
          value: { kind: 'Int' as const, value: 5 },
        },
      },
    }
    const err = captureEvalError(() => evaluate(tree))
    expect(err.code).toBe('option-input-not-option')
  })
})
